/** Product-grounded review drafts. Confirm the operator and jurisdiction with counsel before publication as binding policies. */
export type LegalDocumentId = "privacy" | "terms" | "disclosures";
export type LegalSection = { id: string; title: string; paragraphs: string[] };
export type LegalDocument = { title: string; summary: string; sections: LegalSection[] };
export const LEGAL_REVISION = "2026-10-06";
export const LEGAL_REVISION_LABEL = "6 October 2026";
const section = (id: string, title: string, ...paragraphs: string[]): LegalSection => ({ id, title, paragraphs });

export const LEGAL_DOCUMENTS: Record<LegalDocumentId, LegalDocument> = {
  privacy: {
    title: "Privacy Policy",
    summary: "How the current Veyra application handles account information, identity details, team activity, browser storage and your privacy requests.",
    sections: [
      section("scope", "Scope, status and responsibility",
        "This document describes the information handled by the current Veyra website and application, including personal workspaces, shared business accounts, staff administration, support conversations and Scout. In this draft, Veyra refers to the product. It does not identify a verified incorporated operator, licensed financial institution or data controller. The responsible legal entity, service address and jurisdiction-specific notices must be confirmed before this text is adopted for a public financial service.",
        "The current release includes an internal ledger and account workflows. Do not submit real government identifiers, actual card credentials or confidential customer records to a pre-integration environment. A working registration form, approval screen or account number is not evidence that Veyra has opened a regulated bank account or completed an external identity verification. Read the Terms of Service and Disclosures alongside this notice; they explain those product boundaries."),
      section("account-data", "Account and application information",
        "Creating and maintaining a login can involve your name, email address, password-derived authentication record, account type, profile information and preferences. Business features can additionally involve a business name, team invitation addresses, roles, limits and the association between a teammate's login and the shared business account. Information you enter is used to populate the account and carry out the functions you request.",
        "The application forms support more sensitive fields, including date of birth, contact and residential details, citizenship, government identification details, tax identifiers, occupation, income range and source of funds. Business forms also support formation details, business addresses, industry information and beneficial-owner information. These are categories the software can collect, not a representation that every field is legally necessary in every country. Live collection requires a confirmed legal basis, appropriate safeguards and a reviewed onboarding process."),
      section("activity-data", "Financial activity and related records",
        "The application stores internal account balances and transaction records, including amounts, dates, references, descriptions, counterparties, categories, payment methods and status. Depending on the features used, records can also include card controls, invoices, payees, scheduled bills, savings pockets, rewards, budgets, disputes and digital-asset positions. A statement or export may combine several of these categories into a downloadable file.",
        "Financial-looking records can describe internal-ledger activity rather than externally settled money. Their classification does not make them harmless from a privacy perspective: notes, merchant names and recipient information can still identify people or reveal sensitive relationships. Avoid unnecessary personal details in reference fields. If you enter information about another person, ensure that you have authority to share it for the particular purpose and that you have provided any notice required by applicable law."),
      section("security-data", "Authentication and device information",
        "The server stores salted password hashes rather than a recoverable copy of your chosen password. Sessions involve tokens, creation and expiry information, revocation state and device-related records. Browser or device descriptions and a generated browser identifier support session grouping and security controls. Network addresses and request information may also be processed by abuse controls, the server or the hosting environment; the hosting provider's logging arrangements require separate operational review.",
        "When enabled and enrolled, two-factor authentication, recovery codes and passkeys introduce additional authentication records. Passkey verification uses public-key credentials and device or authenticator responses; the application does not need to receive the fingerprint or face image used to unlock your authenticator. Do not share passwords, authentication codes, recovery codes or session tokens with another teammate or include them in a support conversation."),
      section("purposes", "How information is used",
        "Information supports account access, the display of your saved activity, processing of internal-ledger instructions, team permissions, monthly spending checks, statement generation and support case handling. It also supports application review, security investigations, troubleshooting and audit records. These purposes describe implemented workflows; they are not a blanket authorization to use account data for unrelated advertising, profiling or automated eligibility decisions.",
        "Any live deployment must identify the lawful basis applicable to each purpose and location. Depending on the circumstances, relevant bases may include providing a requested service, meeting an applicable legal obligation, a properly assessed legitimate interest or consent where required. This draft does not assume that all such bases apply to every user, and agreeing to general terms is not a substitute for a specific consent that the law requires."),
      section("team-visibility", "Shared business accounts and teammate attribution",
        "A shared business account is not a private workspace for each employee. Users with the relevant account permissions can see shared business records. The owner and authorized teammates may see member names, roles, invitation status, configured limits and monthly usage. Staff access is separately controlled by administrative permissions. Review the account's actual sharing arrangements before adding confidential information or inviting a new teammate.",
        "For covered outgoing payments, the updated server associates the transaction with the authenticated person who performed it. That attribution is used to calculate individual monthly spending, enforce limits and review account activity. Removing a teammate does not erase financial records they helped create. Older transactions without a reliable initiating-user identity remain unattributed rather than being assigned to a person by inference. The business should explain this monitoring to its workers and meet any applicable employment or data-protection obligations."),
      section("scout", "Scout analysis and conversation history",
        "The current Scout experience derives answers and estimates from saved account activity using application-side analysis. It can identify patterns in spending and present planning suggestions, but it does not negotiate with merchants, issue funded savings credits or make binding financial decisions for you. The current answer flow does not send Scout questions to an external generative-model service. A future model integration would require a fresh assessment of what is sent, to whom, for what purpose and under what retention arrangements.",
        "Scout conversation history can be stored in local browser storage, with a bounded recent history saved for the workspace. The Clear conversation control resets the displayed conversation and its locally saved history; it does not erase source transactions, server audit records or conversations copied elsewhere. Signing out should not be assumed to clear every locally stored preference or Scout history. Use browser storage controls on shared devices and avoid entering secrets into conversational prompts."),
      section("browser-storage", "Browser storage, cookies and external resources",
        "The current client keeps its session token in memory and, where permitted, browser local storage or session storage. A restricted-preview fallback can use the browser window's name to maintain the session across a reload. The client also stores a generated device identifier for session grouping. Clearing site data can sign you out, reset recognition of your browser and remove locally saved Scout history, but it does not delete the account's server-side records.",
        "The site loads web fonts from Google-hosted resources, which can expose ordinary connection information, such as an IP address and browser request metadata, to that provider. Optional sign-in and anti-abuse integrations can introduce additional provider requests and storage when enabled. This notice is not a claim that every deployment is cookie-free or that a cookie-consent system has been implemented. Before introducing analytics, advertising or non-essential tracking, the operator must inventory the technologies and implement any notice and choice mechanisms required in the relevant locations."),
      section("address-suggestions", "Google address suggestions during signup",
        "When enabled, the home and business address fields offer optional Google Maps address suggestions. After you type at least three characters, the address text and a short-lived search-session identifier are sent through Veyra's server to Google Places. Selecting a suggestion sends its place identifier to obtain street, locality, state and postal information. The address-lookup request does not include your name, email, password, SSN or the other application fields. Google receives the server connection used for the lookup; this integration does not request your device's precise location.",
        "You can choose Enter address manually before typing to stop Google lookups for that field. Manual entry remains available when the service is disabled, has no match, reaches a request limit or cannot connect. The suggestions currently support US addresses to match this application's existing validation. They are not proof of residence, postal deliverability or identity. Review the filled fields, add any apartment or suite, and correct missing or inaccurate information before submitting.",
        "Prediction lists are used transiently for display, not saved as an address database or retained in browser storage. The server temporarily associates returned place identifiers with the search session to validate a selection. Your selected address becomes part of the application only when you submit the form, under the account-information and retention provisions above. Google processes service data under its own Privacy Policy at https://policies.google.com/privacy. Google Maps/Google Earth Additional Terms of Service at https://maps.google.com/help/terms_maps/ apply to use of Google's service. Review those provider documents as well as Veyra's notices; availability does not imply that Google has verified your application."),
      section("service-providers", "Service providers and external connections",
        "Some capabilities depend on deployment configuration. Supported integrations include external authentication, anti-abuse checks, transactional email and market-price retrieval. Enabling an integration can disclose the information needed for that operation, such as an email recipient and message content to a mail provider, authentication assertions to a sign-in provider or browser interaction information to an anti-abuse provider. A supported integration should not be assumed to be active merely because a corresponding button appears.",
        "The current implementation does not establish an advertising-data sales workflow, but a code review alone cannot certify every operator, hosting or vendor practice. This draft therefore does not make an unverified organization-wide promise about data sales, targeted advertising or all third-party disclosures. The operator must publish an accurate vendor inventory and any required sale, sharing, opt-out or sensitive-data notices before the relevant processing takes place."),
      section("staff-and-disclosure", "Staff access and other disclosures",
        "Authorized staff may access account, review, support or operational information within their assigned permissions. Support messages are stored as cases and may be accessible to staff handling the case. If email delivery is configured, correspondence and case notifications may also pass through an email provider. A notification preference does not necessarily remove information from an existing case or audit trail.",
        "Requests for information from authorities or other third parties require assessment of the applicable law, the request's validity and the data actually needed. A business transfer or change of operator can also require additional notice and safeguards. This text is not an unrestricted consent to disclose your records to any requester, nor a promise that an operator can disregard a legally binding obligation. Any future partner financial institution would need its own clearly identified role and notices."),
      section("retention", "Retention, correction and deletion",
        "Account data, internal financial records, application details and support cases persist in the current database until an applicable administrative or technical process changes them. Certain audit records are designed to be append-only. The current release does not provide a comprehensive automatic retention schedule or a self-service account-erasure workflow. No specific deletion deadline or universal retention period is represented as implemented by this draft.",
        "Before production use, the operator must set and enforce category-specific retention periods, including rules for logs, identity information, local browser data, support records and backups. Correction or deletion requests may need to be balanced with record-integrity requirements, fraud investigation and applicable legal duties. Preserving a financial record does not justify keeping unrelated information indefinitely. A request should identify the record or category at issue without resending the underlying sensitive identifier."),
      section("rights-and-requests", "Your choices and privacy requests",
        "Depending on the law that applies, you may have rights to request access, correction, deletion, restriction, portability or information about disclosures, and to object to certain processing or withdraw consent where processing depends on it. Some jurisdictions provide complaint or appeal rights. Their availability, exceptions and response periods depend on the actual operator, processing and location; this draft does not replace those statutory rights or require you to waive them.",
        "Use the linked support form or your signed-in support conversation to raise a privacy request and label the subject clearly, for example Privacy request — account access. Provide a contact address, the type of request and enough non-sensitive context to identify the relevant account. Verification of identity or authority may be needed before records can be released or changed. Do not send passwords, complete tax identifiers, identity-document images or authentication secrets through a general support form."),
      section("security-limits", "Security measures and their limits",
        "The application includes password hashing, session revocation, role-based permissions, transactional ledger writes and audit controls. These measures reduce particular risks but are not a certification of security, regulatory compliance, availability or encryption across every environment. Transport security, storage protection, backups, incident response and independent testing must be configured and verified for the deployment that actually handles information.",
        "You can help protect your information by using a unique password, enrolling available additional authentication, reviewing active sessions and revoking unfamiliar sessions promptly. Signing out of one browser does not necessarily revoke every other device session. If you suspect unauthorized access, use the session controls and contact support with the time and non-sensitive details of the concern. Mandatory incident-notification duties, if applicable, are governed by law rather than a promised notification timetable in this draft."),
      section("international", "International processing and regional requirements",
        "Hosting, email, authentication and other providers may process information in a country different from your own, depending on the chosen deployment. No hosting location, international-transfer mechanism or regulatory registration is confirmed by this notice. The operator must identify actual locations and establish the safeguards, contracts and regional disclosures required before transferring regulated personal information.",
        "The application currently contains United States-oriented identity and currency fields. Those fields do not establish that the service is licensed in the United States, that only United States law applies, or that access from another country is authorized. A launch in Nigeria, the United States, the European Economic Area, the United Kingdom or another market requires a jurisdiction-specific review. Your physical location must not be inferred to be the company's governing jurisdiction."),
      section("children", "Children and information supplied by others",
        "The account application is designed for adults and is not intended as a children's financial or educational service. Do not create an account for a child or submit a child's identifiers in a pre-integration environment. If you believe that information relating to a child has been provided, contact support without adding further sensitive details so the operator can assess appropriate access restrictions and handling under the applicable rules.",
        "Business administrators who provide teammate, owner or customer information must have appropriate authority to do so. An invitation does not eliminate the invited person's privacy rights. Where several people share responsibility for a record, the operator may need to confirm who is authorized to request changes; shared access should never be treated as permission to impersonate another person."),
      section("changes-and-contact", "Changes, versioning and contact",
        "The revision date identifies this expanded product description, not a verified record that every user accepted a new policy on that date. A material change in data use, a new financial provider, a new external AI service or a different responsible operator may require advance notice, a new lawful-basis assessment or renewed consent. Updating the date on a page alone does not accomplish those steps.",
        "For questions, use the support link below and identify the Privacy Policy section you are asking about. The public legal-entity details, designated privacy contact, applicable authority and retention schedule remain items for operator and legal review. Until these have been confirmed, do not treat illustrative company addresses, illustrative branding or example email domains elsewhere in the product as verified privacy-contact details.")
    ]
  },
  terms: {
    title: "Terms of Service",
    summary: "Detailed conditions for using the current application, with specific rules for shared accounts, spending limits, Scout, confirmations and digital assets.",
    sections: [
      section("status-and-scope", "Status of these terms and the service",
        "These terms are a review draft for the current Veyra product. They describe expected use and implemented limits, but do not identify a confirmed contracting entity, governing jurisdiction or licensed financial partner. The draft must be reviewed and adopted by the responsible operator before being relied on as a binding public service agreement. The revision date is a document version, not a representation that historical users have given renewed consent.",
        "Veyra currently provides account interfaces, an internal ledger, analysis, shared-business controls and related workflow tools. A recorded balance, transfer, card, deposit, invoice payment or digital-asset position does not by itself establish that external money moved, a card network processed an instruction, or an asset is held in custody for you. Access to this release is not an invitation to deposit real funds. Read the Disclosures for the distinction between application records and external settlement."),
      section("eligibility", "Eligibility and authorized access",
        "Use the application only if you are an adult with the legal capacity and authority needed for your use. If you act for a business, you must be authorized to provide its information, invite users and issue the instructions you submit. You must not use another person's identity, create an account by impersonation or represent that you have authority you do not hold.",
        "Technical access from a location does not establish legal eligibility for a financial service there. Availability may depend on account review, configured features, applicable restrictions and any future provider's terms. An approved application state in the software is not a representation that an external bank, regulator or identity-verification provider has approved you. Any live eligibility rules must be stated separately for the service and market being offered."),
      section("credentials", "Credentials and account security",
        "Keep your login credentials, passkeys, recovery codes and additional authentication factors confidential. Each teammate should use their own login so that permissions and payment attribution work correctly. Do not share the owner's credentials to avoid a teammate limit. Review active sessions and notify support promptly if you believe your access has been compromised or a payment was performed by someone without authority.",
        "You are expected to take reasonable care with the devices and credentials you control, but this draft does not assign every unauthorized action to you regardless of its cause or remove protections required by law. Session, password and security controls must be used according to their actual scope: signing out of one session should not be assumed to close all sessions or erase browser-stored data."),
      section("address-suggestions", "Optional Google Maps address entry",
        "Where configured, Veyra uses Google Places to suggest home and business addresses and fill related application fields after you choose a result. This is an optional typing aid. You remain responsible for confirming that the street, unit, locality, state and postal information describe your own applicable address. A suggestion is not an identity check, proof of residence, guarantee of deliverability or determination that an account can be opened.",
        "Use of Google Maps features is subject to the Google Maps/Google Earth Additional Terms of Service at https://maps.google.com/help/terms_maps/ and Google's Privacy Policy at https://policies.google.com/privacy. These provider terms apply in addition to the applicable Veyra terms. You can enter the address manually without requesting Google suggestions. The operator must activate the provider service, maintain appropriate API restrictions and assess the applicable Google Maps Platform terms, including any regional conditions, before enabling it. Provider failures or absent suggestions do not prevent manual submission of an otherwise valid application."),
      section("funding-and-withdrawal-requests", "Funding instructions, pending deposits and crypto requests",
        "The Add Funds catalog distinguishes a described funding option from an active service. ACH bank linking and debit-card collection currently await provider activation, even when an administrator has enabled instructions for those options. The bank-details preview does not accept or store external account information. No trial deposits, card tokenization or charges originate from this screen. A future provider connection would require explicit authorization, bank-access verification, transaction and verification limits, secure handling of credentials and a separate transfer authorization. Passing an ownership check would not itself authorize a debit or guarantee availability of funds.",
        "Zelle entries are manual receiving instructions supplied for the individual member, not a Veyra-operated Zelle integration or enrollment service. Use your own participating bank’s service and independently confirm that the enrolled email or US phone number and recipient name match before sending. Your bank and the receiving institution determine eligibility, limits and timing. Veyra does not guarantee delivery or reversibility. Direct-deposit and wire instructions similarly require verified receiving details; opening these screens does not enroll you in payroll, initiate a wire or establish an external bank account. Never use internal-ledger account details for real transfers.",
        "An authorized administrator can configure the funding methods and instructions displayed for each account. Those entries may identify a source, receiving bank, recipient or reference requirements, but editing an entry does not create a linked external account, tokenize a card or activate a payment processor. Before using any real-world bank instructions, verify them through an independently trusted channel. Do not enter full card numbers, security codes, passwords, private keys or recovery phrases in instruction or reference fields.",
        "Submitting an add-funds request records a pending request rather than collecting outside money or increasing the available balance. A staff member with the separate balance-adjustment permission must confirm independent receipt and record supporting evidence before the internal ledger is credited. A rejected request does not credit the account. A processing illustration, uploaded record from an older interface, or the existence of a pending request is not proof that a bank or check-collection service accepted funds.",
        "Crypto withdrawal requests debit the specified available units at the moment the request is recorded; they do not broadcast a transaction to a blockchain. A recorded request cannot be cancelled or reversed, and the debited units cannot also be sold or requested again. Address syntax and checksum checks do not establish ownership of a destination, guarantee compatibility with its recipient, or ensure that a transfer would be recoverable. No network fee, transaction hash or confirmation is invented by this request-only flow. Actual custody, fee quotation, signing, compliance review and broadcasting require a separately integrated live service."),
      section("records-and-instructions", "Accurate information and instructions",
        "Before submitting an instruction, check the amount, currency, recipient, payment method, selected card and any related schedule. Maintain accurate account and business information and correct errors through the available controls or support. You must have authority to provide information about counterparties, customers and workers. Do not put unnecessary sensitive identifiers in payment descriptions, support messages or Scout prompts.",
        "A client-side preview, animation or calculation is not authoritative acceptance of an instruction. The server may reject a request because of permissions, account state, a spending limit, unavailable information, an insufficient recorded balance or another applicable control. A displayed estimate of the balance after an action is not a promise that the action will be accepted or that an external recipient will receive money."),
      section("payment-confirmation", "Payment confirmation and uncertain outcomes",
        "The updated transfer and manual bill-payment flows wait for a server response before displaying a successful outcome. A successful response confirms the internal-ledger action described in that response. It does not establish bank settlement, card-network acceptance, delivery through a named external payment system or receipt by an outside beneficiary. Preserve the reference and review the resulting transaction record when checking an instruction.",
        "If an internal payment is confirmed but the subsequent balance refresh fails, the application may retain the confirmed outcome and ask you to refresh rather than resend. A network interruption can also leave an outcome uncertain. In either situation, do not repeatedly submit the same instruction to test whether it worked. Check transaction history and contact support with the reference and approximate time. The release does not represent a general end-to-end exactly-once execution or provider reconciliation guarantee."),
      section("business-roles", "Shared accounts and business responsibilities",
        "The business owner is responsible for choosing appropriate users, reviewing roles and promptly removing access that is no longer needed. Admin and Member roles can have spending capabilities within the applicable controls; Bookkeepers retain read-only spending permissions. The owner is not subject to an individual teammate monthly cap. That exemption is not a removal of every account, card, permission or other transaction control.",
        "The business should communicate its own purchasing and approval policies separately. A Veyra role or limit is a software permission, not an employment contract, purchasing mandate or multi-person approval process. The current update does not introduce a new limit-edit endpoint or a payment approval queue. Shared account information may be visible to other authorized users, and removing a teammate does not remove the transaction records associated with that person's prior activity."),
      section("monthly-limits", "Monthly teammate spending limits",
        "Covered outgoing spending by an Admin or Member is checked against the stored limit for that authenticated teammate within the shared business. The period is a UTC calendar month, starting at 00:00 UTC on its first day and ending immediately before the next month's first day. It is not a rolling thirty-day allowance or a period defined by the browser's local timezone. A zero-dollar cap permits no covered outgoing spending; it does not mean unlimited access.",
        "The same allowance combines transfers, card payments, manually executed scheduled bills and crypto purchases. Usage is the gross amount of negative, actor-attributed ledger entries in cleared or pending status during the period. Deposits, incoming payments, rewards and asset sales do not replenish that gross allowance. Moving existing funds between your own savings pockets is excluded. A separately configured card limit or another permission gate can still reject a payment that fits within the teammate allowance.",
        "The server checks current access and allowance in the same write transaction as a covered debit and its attribution record. Submitting simultaneous requests, using a new browser session or supplying a different actor in a request does not create a fresh allowance. If a covered instruction exceeds the remaining allowance, it is refused rather than intentionally split or silently increased. Limits are controls on the internal ledger, not a guarantee against every possible misuse or every future external-provider event."),
      section("legacy-attribution", "Historical records and tracking limitations",
        "The update does not reconstruct the identity of people who initiated older transactions when that identity was not recorded. Unattributed historical activity is preserved and excluded from individual teammate usage instead of being guessed or reassigned. Any already-attributed qualifying transaction in the current UTC month still counts. The tracking activation date is metadata and is not an additional exclusion of otherwise eligible earlier entries.",
        "As a result, the first enforced month on an existing installation may not reflect every purchase a teammate made before reliable attribution was available. A low usage figure must not be interpreted as proof that a person made no earlier purchases. Account owners should consider this limitation when reviewing spending and should not treat the new control as a retrospective audit of all employee activity."),
      section("schedules-and-invoices", "Schedules, invoices and savings pockets",
        "Creating a schedule does not reserve a teammate's allowance. Manual execution is checked against the allowance of the authenticated person who executes it, not automatically the person who created the schedule. A refused bill payment does not advance the schedule as though the payment succeeded. Schedule and autopay labels do not, on their own, prove that an external recurring-payment mandate or unattended payment service has been activated.",
        "Marking an invoice as paid records a status and associated internal activity where implemented; it is not independent proof of a customer's bank payment. Savings pockets allocate existing recorded funds within the account and do not establish separate deposit ownership, interest-bearing accounts or additional deposit-insurance coverage. Review these features as organizational tools unless a separately identified live service agreement says otherwise."),
      section("scout-and-analysis", "Scout, estimates and decision support",
        "Scout provides informational analysis of saved account activity, including spending summaries, possible recurring costs and planning estimates. Reviewing an estimate does not contact a merchant, negotiate a new price, cancel a service, transfer ownership of funds or create a funded savings credit. Automatic random Scout credits have been disabled, and the retired credit-application endpoint rejects requests rather than allowing a client-provided estimate to increase the balance.",
        "Historical Scout figures remain in the ledger and can include entries created by earlier internal-ledger behavior. Their presence is not a promise of future savings or proof of recovered money. Projections, match indicators and suggested buffers are not guarantees, independent audits or individualized investment, tax or legal advice. Verify important information before acting and make any supplier change or financial decision through an appropriately authorized process."),
      section("digital-assets", "Digital assets and market information",
        "The digital-asset interface can display third-party prices, charts and internal buy or sell records. These features do not establish that an exchange executed a trade, that Veyra controls blockchain keys or that assets have been delivered to an on-chain address. Do not send cryptocurrency to an address or account merely because the interface displays a digital-asset balance. Any live custody, execution or withdrawal service requires identified providers, eligibility terms and additional disclosures.",
        "Prices can be delayed, cached, incomplete or unavailable. Internal trade acceptance depends on available quotes and applicable controls; a displayed quote is not an unconditional offer to execute through an outside market. Digital assets can be highly volatile and can lose all value. Stablecoin branding does not eliminate depegging, issuer, reserve, redemption, technology or counterparty risk. Team crypto purchases count toward the teammate allowance; selling does not restore that allowance."),
      section("rewards-fees", "Rewards, fees and promotional information",
        "The update disables unfunded Scout credits but does not turn the existing cashback ledger into a funded rewards program. Recorded rewards and internal redemption behavior are not evidence that an external sponsor has financed them or that they are withdrawable through a bank. Descriptions such as unlimited, automatic or a percentage rate must be read with the current product limitations, not as an unconditional entitlement to real-world payment.",
        "Pricing screens, example plans and fee descriptions must not be treated as a substitute for a confirmed live service schedule. Before a paid or provider-backed financial service is offered, the operator must identify the applicable price, payer, billing and cancellation conditions, taxes where relevant and any separate provider charges. This draft does not invent a subscription collection arrangement, authorize unspecified charges or create a guaranteed reward rate."),
      section("acceptable-use", "Acceptable use and prohibited conduct",
        "Do not use the service for fraud, impersonation, unauthorized access, unlawful activity, malicious software, abusive communications or interference with other users. Do not attempt to bypass team permissions, spending caps, authentication, rate limits or audit controls, and do not exploit internal-ledger credits or errors as if they represented a right to real funds. Report a suspected defect without accessing or publishing someone else's information.",
        "You must not submit information you are not entitled to use or use the product to mislead another person about settlement, licensing, account insurance or asset ownership. Reasonable security testing should be coordinated with the operator and confined to authorized accounts and environments. These expectations do not restrict legally protected activity or override a separately agreed security-testing authorization."),
      section("content-and-exports", "Content, reports and intellectual property",
        "Your entries and uploaded or supplied materials remain subject to the rights of their owners. Providing them to the application permits the processing needed for the function you request, subject to applicable law and the Privacy Policy; it is not a transfer of all ownership rights to Veyra. Do not upload another person's protected work or private information without appropriate authority.",
        "Veyra's interface, software and original materials are subject to applicable intellectual-property rights. Third-party names, brands and data retain their respective rights and do not establish endorsement. CSV and PDF exports reproduce available application records; downloading them does not certify their completeness, external settlement or acceptance by a tax authority. You are responsible for protecting downloaded files and checking whether they meet the requirements of the recipient."),
      section("availability-and-restrictions", "Availability, restrictions and ending use",
        "Features may be unavailable because of maintenance, connectivity, provider outages, account review or configured restrictions. Access may be limited where needed to address misuse, security concerns or an applicable legal requirement. Such restrictions should be distinguished from a reversal of financial history: revoking a login or changing access does not itself delete transaction records or establish that a pending external obligation has been cancelled.",
        "You may stop using the application and request help with account closure or data handling. The current release has no comprehensive self-service account-erasure workflow, and stopping use does not automatically remove server records or downloaded copies. The operator must determine any applicable retention and closure obligations before launching a live service. Do not rely on this draft as a promise of continuous availability or a specified support response time."),
      section("warranties-and-rights", "Limitations and non-excludable rights",
        "The preview is provided for evaluation with the limitations described in these documents. No claim is made that it is suitable for holding or transmitting real funds, free from every error or independently certified for regulated use. Analyses and records should be checked against the underlying activity and, where relevant, an actual financial provider's records. A software disclaimer cannot substitute for the controls required to operate a financial service safely.",
        "Nothing in this draft is intended to exclude rights or liability that cannot lawfully be excluded, including mandatory consumer or data-protection rights. No arbitrary monetary liability cap, mandatory arbitration clause, class-action waiver or jurisdiction-specific remedy restriction is created here. The appropriate allocation of risk and remedies must be reviewed for the identified operator, users and launch jurisdictions before final terms are adopted."),
      section("complaints-and-law", "Questions, complaints and governing law",
        "Use the linked support channel to report an error, raise a complaint or request clarification. Include the relevant transaction reference, approximate time and a description of the issue, not authentication secrets or full sensitive identifiers. Preserve records of the request. A support case or dispute status does not itself guarantee reimbursement, card-network chargeback rights, provisional credit or a legal determination.",
        "The contracting entity, governing law, competent courts, any regulatory complaint route and any applicable statutory deadlines have not been confirmed in this review draft. None should be inferred from a sample address, dollar symbol, United States-oriented form or a visitor's location. A final service agreement must specify the appropriate details without removing mandatory protections that apply independently of the agreement."),
      section("changes", "Changes to the product and these terms",
        "A future move from internal-ledger records to live banking, card issuing, payment processing or digital-asset custody is a material change, not a routine wording update. It requires the relevant provider agreements, disclosures, permissions and operating controls. Similarly, new automated approvals, external AI processing or revised spending policies may require additional user notice and consent where applicable.",
        "Keep a copy of the version relevant to your use. The current application does not represent that this page update creates a versioned acceptance record for every user or retroactively changes prior instructions. Contact support if the interface appears inconsistent with these limitations. Until final approval, this document should be used for product and legal review rather than as evidence that the service is licensed or ready for real-money launch.")
    ]
  },
  disclosures: {
    title: "Disclosures",
    summary: "Important explanations of what balances, payment statuses, Scout estimates, rewards and digital-asset features do—and do not—represent.",
    sections: [
      section("current-release", "Current release and review status",
        "Veyra's current release is an internal-ledger financial application with account and workflow features. This disclosure describes that implementation, not a confirmed regulated financial offering. The responsible legal operator, launch jurisdictions, financial partners and production approvals remain subject to confirmation. The presence of a dashboard, registration flow, staff review process or legal page is not evidence of licensing or regulatory approval.",
        "This revision expands the disclosures for the Scout credit restriction, server-enforced teammate limits, payment confirmations and updated dashboards. It does not activate real payment processing, establish custody, fund rewards or validate earlier internal-ledger balances. If you are evaluating the preview, use synthetic information and do not send real funds or digital assets on the strength of a displayed account or asset record."),
      section("banking-insurance", "Bank status, partners and insurance",
        "Veyra is not represented here as a bank, an insured depository institution or a licensed custodian. No partner bank, card issuer, payment-network sponsorship or deposit-insurance arrangement has been verified for this release. Earlier wording suggesting that banking services would be provided by unspecified partner institutions should not be relied upon as a statement that such a relationship already exists.",
        "A dollar balance, routing-like number, account number, card image or banking label does not establish a deposit account at an insured institution. No FDIC, NDIC, FSCS or other deposit or investor-protection coverage is established by these screens. A future provider-backed product must identify the institution, explain eligibility and ownership arrangements, and disclose any insurance limits and exclusions. Digital-asset exposure must not be described as insured bank deposits merely because it appears beside a cash balance."),
      section("balances", "Balances, pending entries and statements",
        "Balances reflect the application's stored records. Some environments contain seeded account activity, manual adjustments or historical credits that have not been matched to external funds. Available, pending, rewards and savings figures describe different internal categories and should not be combined or treated as separately withdrawable money without understanding the records behind them. A displayed total does not independently establish a legal claim against a bank or an asset custodian.",
        "Charts, period comparisons and account summaries are derived from the records and filters available to the application. Missing historical entries, attribution gaps, pending transactions or differences in date boundaries can change a result. Larger fonts and clearer mobile layouts improve readability, not the legal status of an amount. Statements and exports are reporting tools; they are not an external reconciliation, a deposit certificate or a guarantee that a counterparty received payment."),
      section("payments", "Transfers, cards and payment labels",
        "Payment methods and card controls in the current interface operate within the application model. Labels such as ACH, wire, Zelle, card payment, mobile check deposit or delivered card must not be taken as evidence that the named external system was used. A card design does not itself represent an issued, network-enabled credential. A check image or deposit record does not establish collection, clearance or final availability of outside funds.",
        "A server-confirmed transfer or manually executed bill confirms an internal-ledger action. External settlement, beneficiary receipt, reversibility, cut-off times, chargebacks and funds-availability rules would depend on a separately contracted live provider. None of those services should be assumed from a success animation. Verify actual payment delivery using the relevant external institution if a real-world obligation exists outside this preview."),
      section("confirmation-errors", "Confirmation, refresh failures and duplicate risk",
        "The updated send and manual bill flows do not intentionally show a success receipt before the server confirms the action. A declined request should remain a refusal rather than advance a bill schedule or produce a success outcome. However, a successful payment response and a later account-state refresh are separate events: the refresh can fail even after the internal debit has been recorded.",
        "If you receive a refresh warning after confirmation, do not assume that the payment was reversed or resubmit it solely because the visible balance is stale. Network failures can leave an outcome uncertain even without a success screen. Check transaction history, preserve the reference and contact support where needed. The release does not establish a universal exactly-once delivery guarantee across clients, networks and external providers."),
      section("team-limits", "What teammate limits cover",
        "Admin and Member monthly limits apply to the authenticated individual within the shared business account, across transfers, card payments, executed scheduled bills and crypto buys together. A limit of zero blocks covered outgoing spending. Owners are not subject to an individual teammate cap, and Bookkeepers remain read-only for spending. Other account, role and card controls can apply in addition to the monthly rule.",
        "The measurement period is the UTC calendar month. Usage includes gross negative, actor-attributed cleared and pending entries, rather than netting incoming money against purchases. Deposits and sales do not restore allowance; moving funds into or out of the account's own savings pockets is excluded. The check and debit are performed together so competing requests cannot each reuse the same remaining allowance. This protects covered internal operations and is not a representation about unconnected future provider events."),
      section("team-history", "Attribution gaps and remaining allowance",
        "Older transactions may not identify which teammate initiated them. They are not guessed, redistributed among members or silently rewritten by this update. Unattributed history is excluded from individual usage, while qualifying current-month records that already have attribution are included. Tracking activation information describes when the updated tracking was installed, not a guarantee that every earlier transaction is attributable.",
        "This limitation is particularly important during the first month after an existing installation is updated. A displayed remaining allowance can be higher than it would have been if every earlier purchase had an initiating-user record. Owners should review the shared ledger as well as the individual usage display. The cap is not a substitute for accounting reconciliation, employment policies, supervisory review or a multi-person approval workflow."),
      section("scout-estimates", "Scout does not issue new savings credits",
        "Scout estimates are informational. Reviewing an opportunity does not negotiate a rate, contact a merchant, apply a supplier discount or fund your account. Random transfer-related Scout credits have been removed and the former credit-application action is disabled server-side. Changing a monitoring preference does not authorize creation of money, and an estimated annual saving is not an available balance or an offer from a provider.",
        "The application preserves existing financial history rather than reversing it silently. Historical Scout amounts can therefore include historical internal-ledger entries created under earlier behavior. Those entries are not proof that a bill was renegotiated or a refund was recovered. If a future funded savings program is introduced, it will need a genuine source of funds, eligibility rules, verified outcomes and separate terms before any estimated benefit can become an actual credit."),
      section("analytics-and-advice", "Analytics, projections and advice limitations",
        "Scout and dashboard tools organize saved activity and calculate summaries, comparisons or illustrative trends. A projected cash position, recurring-cost match, suggested savings buffer or runway estimate depends on assumptions and available records. It can be incomplete or wrong, especially when transactions are missing, miscategorized, pending or representative of a short period. A percentage labelled as a match or estimate is not a calibrated guarantee of an outcome.",
        "These outputs do not constitute individualized investment, tax, legal or regulated financial advice. No adviser-client, fiduciary or portfolio-management relationship is created by a chat response or dashboard suggestion. Use appropriate independent professional advice for decisions that require it, and verify significant amounts against source records. A suggestion to move existing funds into a savings pocket does not create new funds or establish suitability for your circumstances."),
      section("rewards-and-pricing", "Cashback, rewards and pricing",
        "Ordinary cashback and internal reward redemption remain separate from the disabled Scout credit feature. Their continued operation in the ledger does not establish a funded rewards scheme or an obligation of an outside bank, merchant or network. Historical rates and promotional examples are not guaranteed future returns. A production program would need confirmed funding, eligible transactions, exclusions, redemption rules and procedures for errors or reversals.",
        "Plan prices and benefit descriptions in the current product should be verified against any live agreement before you rely on them. A internal-ledger subscription selection is not evidence of an activated collection mandate. No unspecified provider fee, tax treatment or reward entitlement is established by this disclosure. If a future paid service changes rates or benefits, it must provide the notices and choices required by its agreement and applicable law."),
      section("digital-asset-risk", "Digital-asset, stablecoin and custody risks",
        "Digital-asset displays currently represent internal positions and market information, not proof of executed exchange orders or blockchain custody. A software buy or sell record does not establish segregation of customer property, control of private keys, redemption rights or the ability to withdraw an asset. Before using any future live service, verify the execution venue, custodian, supported network, withdrawal process and legal treatment of assets if a provider fails.",
        "Digital assets can experience extreme price changes, thin liquidity, technical failures, irreversible transaction errors, fraud and changes in legal treatment. You may lose all value in a real investment. Stablecoins can lose their intended peg or face reserve, issuer and redemption problems. Insurance associated with cash deposits, where it genuinely exists, should not be assumed to cover token values, exchange losses or private-key compromise."),
      section("hybrid-wallets", "Connected wallets, reviewed account orders and network boundaries",
        "The crypto workspace distinguishes built-in Veyra account records from external wallets that you connect. A wallet connection requests access to a public address; it does not transfer assets, establish custody, authorize trading, or prove wallet ownership for Veyra authentication. Veyra does not request, store or import private keys or recovery phrases through this interface. Public addresses and balance requests are shared with the selected wallet and its RPC services; a configured Solana reader receives the requested public address through the Veyra server. Those providers may record request metadata under their own policies, and public blockchain records cannot be removed by disconnecting. Wallet connections are held in browser memory rather than stored as Veyra login credentials. Wallet names and extension metadata are self-reported. Install wallets only through sources you independently verify, review permission requests in the wallet itself, and disconnect or revoke permissions when appropriate.",
        "Reviewed buy, sell and swap orders in this workspace are available to active, approved account owners when account trading is enabled. Team members can view the account but cannot initiate these new reviewed orders. Older API purchase paths remain subject to their existing teammate spending controls. Reviews expire and execution rechecks available balances, including units already reserved for pending withdrawals. A swap exchanges internal holdings without crediting or debiting checking and does not bridge between blockchains. Output quantities are rounded down to destination precision, and orders below the supported minimum value are refused. An internal receipt or account-completed status does not mean an exchange, custodian or blockchain executed the instruction.",
        "Ethereum connections require Ethereum mainnet; the balance view currently reads ETH and the specified Ethereum USDC and USDT contracts, not every token a wallet may hold. Bitcoin connections require UniSat's Bitcoin-mainnet chain identity, not merely a livenet label shared with other chains. Bitcoin balances exclude unconfirmed funds. Solana connections share a public address; Phantom's selected network is not exposed through this connector. An optional server-side reader independently checks Solana-mainnet genesis and reads finalized SOL balances, but does not index all Solana tokens. Missing readers, failed requests and unsupported balance values are shown as unavailable rather than zero. These readouts are not a reconciled custody statement and are never added to Veyra account totals.",
        "A receive QR contains your connected external wallet address, not a Veyra deposit address. Confirm the network, token and complete destination independently before sharing or using it. Coins received there do not credit the Veyra account ledger. External cash gateways, custody, wallet swaps, gas or fee estimates and broadcasting are not connected in this release. An account send request only reserves holdings, remains cancellable while pending, and has no blockchain transaction hash. No network fee is collected by that request-only flow. Before any future live activation, provider contracts, asset backing, destination screening, network-specific signing, fee review, confirmation and reorganization handling, reconciliation and updated user consent must be established.",
        "If a confirmation response is lost, resume or retry the same reviewed order rather than starting a new one. The account service stores a completed result by review identifier to prevent that identifier from executing twice. The browser retains the pending review identifier for recovery where session storage is available; blocked storage or using a different device can limit this convenience. Account order history remains authoritative. This protection is scoped to internal orders and does not establish an exactly-once guarantee for future external providers or blockchain settlement."),
      section("market-data", "Prices, chart history and quote availability",
        "Market information can originate from third-party feeds and be cached or delayed. A displayed price is an indication based on the data available at that moment, not a firm external execution quote. Charts may have limited history or periods of unavailability. The internal trade path can refuse a purchase when an acceptable quote is unavailable; a screen refresh or previous quote does not compel acceptance of a later instruction.",
        "Differences can arise between a displayed portfolio value, an internal trade calculation and a price shown elsewhere. Such differences may reflect timing, rounding, data source or market conditions rather than a guaranteed trading opportunity. Do not rely on a chart alone for valuation, financial reporting or execution decisions. The application does not promise continuous data availability or independent verification of every provider value."),
      section("schedules-and-disputes", "Schedules, automation and dispute workflows",
        "Scheduling records, autopay preferences, invoice reminders and card-shipping statuses are application workflows. Their presence does not verify a live payment mandate, a dispatched physical card, an email delivery or an external provider's commitment. Creating a bill schedule does not reserve funds or teammate allowance; a manual execution is evaluated against the authenticated executor's current controls.",
        "Similarly, opening a support case or dispute records a request for review. It does not automatically create statutory chargeback eligibility, provisional credit, reimbursement or a promised resolution date. If an issue concerns an actual payment through another institution, preserve that institution's reference and follow its applicable reporting process as well. Do not assume that a Veyra case extends an external provider's or a law's reporting deadline."),
      section("security-and-availability", "Security, integrations and operational readiness",
        "The application includes authentication, role checks, session controls, audit records and atomic ledger updates, but these are not certifications of regulatory compliance or a guarantee against all failures. A live service also needs verified provider integration, reconciliation, idempotency, protection of sensitive data, incident handling, backups, recovery testing and monitoring. Automated tests and responsive-browser checks are useful engineering evidence, not an independent security audit.",
        "Email, external authentication, anti-abuse and market feeds depend on configuration and provider availability. Supported code is not the same as an activated production contract. A feature can be unavailable in one environment and enabled in another. Review the Privacy Policy for the information involved, and do not assume that a disabled email provider makes a stored support case disappear or that a disabled integration removes all privacy obligations."),
      section("regional-and-contact", "Regional review, questions and future changes",
        "This draft does not select a governing jurisdiction, assert a particular licence or confirm an applicable complaints authority. The operator must establish the legal entity, launch markets, service providers and regulatory treatment before offering live services. Required notices can differ by product and location; banking-style terminology, a sample address or a visitor's location must not be used to fill those gaps by assumption.",
        "Use the support channel below if you need clarification or see a statement that appears inconsistent with these limitations. Include the page, feature and non-sensitive reference involved. These disclosures do not remove mandatory consumer or privacy rights. A future transition to real money movement, funded rewards or digital-asset custody requires fresh review and clear provider-specific information; revising this page alone cannot authorize that transition.")
    ]
  }
};
